WITH lines AS (SELECT id, service, host, log_ts, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, attr_value) SELECT host, SIZE(COLLECT_SET(service)) AS num_services, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, SORT_ARRAY(COLLECT_SET(host)) AS host_list, COUNT(DISTINCT host) AS distinct_hosts, COUNT(*) FILTER (WHERE k = 'region') AS region_rows, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count FROM lines GROUP BY host HAVING COUNT(*) FILTER (WHERE k = 'region') >= 1 ORDER BY distinct_hosts DESC
